export function renderTable(rows: Row[]): string {
  const cut = (s: unknown, n: number) => { const t = s == null ? "" : String(s); return t.length > n ? t.slice(0, n - 1) + "…" : t }
  const lines = [`${"date".padEnd(10)}  ${"title".padEnd(48)}  ${"company".padEnd(28)}  location`]
  for (const r of rows) lines.push(`${cut(r.date, 10).padEnd(10)}  ${cut(r.title, 48).padEnd(48)}  ${cut(r.company, 28).padEnd(28)}  ${cut(r.location, 30)}`)
  return lines.join("\n")
}

export function renderPlain(rows: Row[]): string {
  return rows.map((r) => [r.title, `${r.company ?? "—"} · ${r.location ?? "—"}${r.date ? ` · ${r.date}` : ""}`, r.url].join("\n")).join("\n\n")
}
